import {FetchContentResult, validateData} from "@enonic/nextjs-adapter";
import {fetchContent, fetchContentPathsForAllLocales} from "@enonic/nextjs-adapter/server";
import MainView from '@enonic/nextjs-adapter/views/MainView';

import "../../../components/_mappings";
import {Metadata} from 'next';
import {draftMode} from 'next/headers';
import React from 'react';

// NB. Using this option with default value bails out static generation !!!
// export const dynamic = 'auto'

// The revalidate option is only available when using the Node.js Runtime.
// This means using the revalidate option with runtime = 'edge' will not work.
export const revalidate = 3600

// PageProps type matches the Next.js route [[...contentPath]]
// where contentPath is optional (can be undefined for root paths)
export type PageProps = {
    countryCode: string,
    contentPath: string[],
}

export default async function Page({params}: { params: Promise<PageProps> }) {
    const {isEnabled: draft} = await draftMode();
    const resolvedParams = await params;

    const data: FetchContentResult = await fetchContent({
        locale: resolvedParams.countryCode,
        contentPath: resolvedParams.contentPath || []
    });

    validateData(data);

    console.debug(`Rendered ${draft ? 'draft ' : ''}page at [/${data.meta.locale}/${data.meta.path}]`);

    return (
        <MainView {...data}/>
    )
};

export async function generateMetadata({params}: { params: Promise<PageProps> }): Promise<Metadata> {
    const resolvedParams = await params;
    const {common} = await fetchContent({
        locale: resolvedParams.countryCode,
        contentPath: resolvedParams.contentPath || []
    });
    return {
        title: common?.get?.displayName || 'Not found',
    };
}

export async function generateStaticParams_disabled(props: { params: PageProps }): Promise<any[]> {
    return await fetchContentPathsForAllLocales('\${site}/');
}

import httpClient from "/lib/http-client"

type MedusaProduct = {
  id: string
  title: string
  handle: string
  thumbnail?: string
  description?: string
}

const BACKEND_URL = "http://localhost:9000"
const PUBLISHABLE_KEY = "pk_c238bc08b8c027a19f13b73b02577c278007b5b294d1cc94942f31e86abf6c17"

export function GET(request: {
  params: { query?: string; start?: string; count?: string; ids?: string[] }
}) {
  const query = request.params.query || ""
  const start = parseInt(request.params.start || "0", 10)
  const count = parseInt(request.params.count || "10", 10)

  try {
    const url = `${BACKEND_URL}/store/products?limit=${count}&offset=${start}` +
      (query ? `&q=${encodeURIComponent(query)}` : "")

    const response = httpClient.request({
      url,
      method: "GET",
      headers: {
        "x-publishable-api-key": PUBLISHABLE_KEY,
      },
      contentType: "application/json",
    })

    if (response.status !== 200) {
      throw new Error(`Medusa returned status ${response.status}`)
    }

    const data = JSON.parse(response.body as string)
    const products: MedusaProduct[] = data.products || []

    const hits = products.map((p) => ({
      id: p.handle,
      displayName: p.title,
      description: p.description || "",
      iconUrl: p.thumbnail || undefined,
    }))

    return {
      status: 200,
      body: JSON.stringify({
        hits,
        count: hits.length,
        total: data.count || hits.length,
      }),
      contentType: "application/json",
    }
  } catch (e) {
    return {
      status: 500,
      body: JSON.stringify({ error: String(e) }),
      contentType: "application/json",
    }
  }
}

"use server"

import { sdk } from "@lib/config"
import { sortProducts } from "@lib/util/sort-products"
import { HttpTypes } from "@medusajs/types"
import { SortOptions } from "@modules/store/components/refinement-list/sort-products"
import { getAuthHeaders, getCacheOptions } from "./cookies"
import { getRegion, retrieveRegion } from "./regions"

export const listProducts = async ({
  pageParam = 1,
  queryParams,
  countryCode,
  regionId,
}: {
  pageParam?: number
  queryParams?: HttpTypes.FindParams & HttpTypes.StoreProductListParams
  countryCode?: string
  regionId?: string
}): Promise<{
  response: { products: HttpTypes.StoreProduct[]; count: number }
  nextPage: number | null
  queryParams?: HttpTypes.FindParams & HttpTypes.StoreProductListParams
}> => {
  if (!countryCode && !regionId) {
    throw new Error("Country code or region ID is required")
  }

  const limit = queryParams?.limit || 12
  const _pageParam = Math.max(pageParam, 1)
  const offset = _pageParam === 1 ? 0 : (_pageParam - 1) * limit

  let region: HttpTypes.StoreRegion | undefined | null

  if (countryCode) {
    region = await getRegion(countryCode)
  } else {
    region = await retrieveRegion(regionId!)
  }

  if (!region) {
    return {
      response: { products: [], count: 0 },
      nextPage: null,
    }
  }

  const headers = {
    ...(await getAuthHeaders()),
  }

  const next = {
    ...(await getCacheOptions("products")),
  }

  return sdk.client
    .fetch<{ products: HttpTypes.StoreProduct[]; count: number }>(
      `/store/products`,
      {
        method: "GET",
        query: {
          limit,
          offset,
          region_id: region?.id,
          fields:
            "*variants.calculated_price,+variants.inventory_quantity,*variants.images,+metadata,+tags,",
          ...queryParams,
        },
        headers,
        next,
        cache: "force-cache",
      }
    )
    .then(({ products, count }) => {
      const nextPage = count > offset + limit ? pageParam + 1 : null

      return {
        response: {
          products,
          count,
        },
        nextPage: nextPage,
        queryParams,
      }
    })
}

/**
 * This will fetch 100 products to the Next.js cache and sort them based on the sortBy parameter.
 * It will then return the paginated products based on the page and limit parameters.
 */
export const listProductsWithSort = async ({
  page = 0,
  queryParams,
  sortBy = "created_at",
  countryCode,
}: {
  page?: number
  queryParams?: HttpTypes.FindParams & HttpTypes.StoreProductParams
  sortBy?: SortOptions
  countryCode: string
}): Promise<{
  response: { products: HttpTypes.StoreProduct[]; count: number }
  nextPage: number | null
  queryParams?: HttpTypes.FindParams & HttpTypes.StoreProductParams
}> => {
  const limit = queryParams?.limit || 12

  const {
    response: { products, count },
  } = await listProducts({
    pageParam: 0,
    queryParams: {
      ...queryParams,
      limit: 100,
    },
    countryCode,
  })

  const sortedProducts = sortProducts(products, sortBy)

  const pageParam = (page - 1) * limit

  const nextPage = count > pageParam + limit ? pageParam + limit : null

  const paginatedProducts = sortedProducts.slice(pageParam, pageParam + limit)

  return {
    response: {
      products: paginatedProducts,
      count,
    },
    nextPage,
    queryParams,
  }
}

