import * as contentLib from '/lib/xp/content';
import * as contextLib from '/lib/xp/context';
import * as nodeLib from '/lib/xp/node';

const REPO = 'com.enonic.cms.hmdb';

function adminCtxDraft<T>(fn: () => T): T {
    return contextLib.run(
        { user: { login: 'su', idProvider: 'system' }, repository: REPO, branch: 'draft' },
        fn,
    );
}

export function ensureLandingPageTemplate(): void {
    log.info('[ensure-landing-page-template] checking…');

    adminCtxDraft(() => {
        // Skip if template already exists
        const existing = contentLib.query({
            query: `type = 'portal:page-template' AND data.supports = '${app.name}:landing-page'`,
            count: 1,
        });
        if (existing.total > 0) {
            log.info('[ensure-landing-page-template] already exists, skipping.');
            return;
        }

        // Find the template folder dynamically — don't hardcode the path
        const templateFolderResult = contentLib.query({
            query: "type = 'portal:template-folder'",
            count: 1,
        });
        if (templateFolderResult.total === 0) {
            log.warning('[ensure-landing-page-template] no template folder found, skipping.');
            return;
        }
        const templateFolderPath = templateFolderResult.hits[0]._path;
        log.info(`[ensure-landing-page-template] creating template under "${templateFolderPath}"`);

        // Create the bare template content
        let created: ReturnType<typeof contentLib.create>;
        try {
            created = contentLib.create({
                parentPath: templateFolderPath,
                contentType: 'portal:page-template',
                displayName: 'Landing Page',
                requireValid: false,
                data: {
                    supports: `${app.name}:landing-page`,
                },
            } as Parameters<typeof contentLib.create>[0]);
        } catch (e) {
            log.error('[ensure-landing-page-template] create failed: ' + (e as Error).message);
            return;
        }

        if (!created) {
            log.error('[ensure-landing-page-template] create returned null');
            return;
        }
        log.info(`[ensure-landing-page-template] created at "${created._path}"`);

        // Set the page descriptor and pre-place the product-showcase part via node API
        const appNameDashed = app.name.replace(/\./g, '-');
        const draftRepo = nodeLib.connect({
            repoId: REPO,
            branch: 'draft',
            user: { login: 'su', idProvider: 'system' },
            principals: ['role:system.admin'],
        });

        draftRepo.modify({
            key: `/content${created._path}`,
            editor: (node: Record<string, unknown>) => {
                (node as Record<string, unknown>)['components'] = [
                    {
                        type: 'page',
                        path: '/',
                        page: {
                            descriptor: `${app.name}:landing`,
                            customized: false,
                            config: {
                                [appNameDashed]: {
                                    landing: {},
                                },
                            },
                        },
                    },
                    {
                        type: 'part',
                        path: '/main/0',
                        part: {
                            descriptor: `${app.name}:product-showcase`,
                            config: {
                                [appNameDashed]: {
                                    'product-showcase': {
                                        heading: 'Featured Products',
                                    },
                                },
                            },
                        },
                    },
                ];
                return node;
            },
        });

        // Push draft → master so the template is immediately live
        const pushResult = draftRepo.push({
            keys: [`/content${created._path}`],
            target: 'master',
            resolve: false,
        });
        const ok = (pushResult.success || []).length;
        const ko = (pushResult.failed || []).length;
        log.info(`[ensure-landing-page-template] pushed to master: ok=${ok} failed=${ko}`);
    });

    log.info('[ensure-landing-page-template] done');
}

