import type { PartProps } from '@enonic/nextjs-adapter';
import type { HttpTypes } from '@medusajs/types';

type ProductShowcaseConfig = {
    heading?: string;
    products?: string | string[];
};

async function fetchProductsByHandles(handles: string[]): Promise<HttpTypes.StoreProduct[]> {
    if (handles.length === 0) return [];

    const backendUrl = process.env.NEXT_PUBLIC_MEDUSA_BACKEND_URL ?? 'http://localhost:9000';
    const publishableKey = process.env.NEXT_PUBLIC_MEDUSA_PUBLISHABLE_KEY ?? '';

    const params = handles.map((h) => `handle[]=${encodeURIComponent(h)}`).join('&');
    const url = `${backendUrl}/store/products?${params}&limit=${handles.length}`;

    try {
        const res = await fetch(url, {
            headers: { 'x-publishable-api-key': publishableKey },
            next: { revalidate: 3600 },
        });
        if (!res.ok) return [];
        const data = await res.json();
        return (data.products as HttpTypes.StoreProduct[]) ?? [];
    } catch {
        return [];
    }
}

export default async function ProductShowcase({ part, meta }: PartProps) {
    const config = part.config as ProductShowcaseConfig | undefined;
    const heading = config?.heading ?? 'Featured Products';
    const raw = config?.products;
    const handles: string[] = raw ? (Array.isArray(raw) ? raw : [raw]) : [];

    const products = await fetchProductsByHandles(handles);
    const countryCode = meta?.locale ?? 'dk';

    return (
        <section style={{ padding: '2rem 0' }}>
            <h2 style={{ marginBottom: '1.5rem', fontSize: '1.5rem', fontWeight: 600 }}>
                {heading}
            </h2>
            {products.length > 0 ? (
                <div
                    style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
                        gap: '1.5rem',
                    }}
                >
                    {products.map((p) => (
                        <a
                            key={p.id}
                            href={`/${countryCode}/products/${p.handle}`}
                            style={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            {p.thumbnail && (
                                <img
                                    src={p.thumbnail}
                                    alt={p.title ?? ''}
                                    style={{
                                        width: '100%',
                                        aspectRatio: '1',
                                        objectFit: 'cover',
                                        borderRadius: '8px',
                                    }}
                                />
                            )}
                            <p style={{ marginTop: '0.5rem', fontWeight: 500 }}>{p.title}</p>
                        </a>
                    ))}
                </div>
            ) : (
                <p style={{ color: '#888' }}>
                    {handles.length === 0
                        ? 'No products selected. Edit this part in Content Studio to choose products.'
                        : 'Products could not be loaded.'}
                </p>
            )}
        </section>
    );
}

